IN_DELETE_SELF = 0x00000400
IN_MOVE_SELF = 0x00000800
IN_Q_OVERFLOW = 0x00004000
IN_IGNORED = 0x00008000
IN_ISDIR = 0x40000000
IN_ONLYDIR = 0x01000000
IN_DONT_FOLLOW = 0x02000000
IN_EXCL_UNLINK = 0x04000000

WATCH_MASK = (
    IN_MODIFY
    | IN_ATTRIB
    | IN_CLOSE_WRITE
    | IN_MOVED_FROM
    | IN_MOVED_TO
    | IN_CREATE
    | IN_DELETE
    | IN_DELETE_SELF
    | IN_MOVE_SELF
    | IN_ONLYDIR
    | IN_DONT_FOLLOW
    | IN_EXCL_UNLINK
)
EVENT = struct.Struct("iIII")
EMPTY_DIGEST = hashlib.sha256(b"").digest()
RECONCILE_INTERVAL = 60.0


@dataclasses.dataclass
class Record:
    dev: int
    ino: int
    size: int
    mtime_ns: int
    ctime_ns: int
    digest: bytes
    status: str = "OK"
    reason: str = ""
    exists: bool = True

    @property
    def identity(self) -> Tuple[int, int]:
        return self.dev, self.ino


class Inotify:
    def __init__(self) -> None:
        libc_name = ctypes.util.find_library("c")
        if not libc_name:
            raise RuntimeError("cannot find libc")
        self.libc = ctypes.CDLL(libc_name, use_errno=True)
        self.libc.inotify_init1.argtypes = [ctypes.c_int]
        self.libc.inotify_init1.restype = ctypes.c_int
        self.libc.inotify_add_watch.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_uint32]
        self.libc.inotify_add_watch.restype = ctypes.c_int
        self.libc.inotify_rm_watch.argtypes = [ctypes.c_int, ctypes.c_int]
        self.libc.inotify_rm_watch.restype = ctypes.c_int
        self.fd = -1
        self.wd_to_dir: Dict[int, str] = {}
        self.dir_to_wd: Dict[str, int] = {}
        self.unwatched_dirs: Dict[str, str] = {}
        self.warned_enospc = False
        self.degraded_reason = ""
        self.open()

    def open(self) -> None:
        if self.fd >= 0:
            os.close(self.fd)
        flags = os.O_NONBLOCK | os.O_CLOEXEC
        self.fd = self.libc.inotify_init1(flags)
        if self.fd < 0:
            err = ctypes.get_errno()
            raise OSError(err, os.strerror(err))
        self.wd_to_dir.clear()
        self.dir_to_wd.clear()
        self.unwatched_dirs.clear()

    def add(self, directory: str) -> bool:
        if directory in self.dir_to_wd:
            return True
        raw = os.fsencode(directory)
        wd = self.libc.inotify_add_watch(self.fd, raw, WATCH_MASK)
        if wd < 0:
            err = ctypes.get_errno()
            if err in (errno.ENOENT, errno.ENOTDIR):
                self.unwatched_dirs.pop(directory, None)
                return True
            if err == errno.EACCES:
                self.unwatched_dirs[directory] = (
                    "directory could not be watched: permission denied"
                )
                return True
            if err == errno.ENOSPC:
                if not self.warned_enospc:
                    self.warned_enospc = True
                    print(
                        "appendwatch: inotify watch limit reached, some directories are "
                        "unwatched; raise fs.inotify.max_user_watches",
                        file=sys.stderr,
                    )
                if not self.degraded_reason:
                    self.degraded_reason = (
                        "inotify watch limit reached; monitoring was incomplete"
                    )
                return False
            raise OSError(err, os.strerror(err), directory)
        self.unwatched_dirs.pop(directory, None)
        previous = self.wd_to_dir.get(wd)
        if previous is not None and previous != directory:
            self.dir_to_wd.pop(previous, None)
        self.wd_to_dir[wd] = directory
        self.dir_to_wd[directory] = wd
        return True

    def remove(self, directory: str) -> None:
        self.unwatched_dirs.pop(directory, None)
        wd = self.dir_to_wd.pop(directory, None)
        if wd is None:
            return
        if self.wd_to_dir.get(wd) == directory:
            self.wd_to_dir.pop(wd, None)
        if self.libc.inotify_rm_watch(self.fd, wd) < 0:
            err = ctypes.get_errno()
            if err not in (errno.EINVAL, errno.EBADF):
                raise OSError(err, os.strerror(err), directory)

    def read(self) -> Iterable[Tuple[str, int, int, str]]:
        while True:
            try:
                data = os.read(self.fd, 1024 * 1024)
            except BlockingIOError:
                return
            if not data:
                return
            offset = 0
            while offset + EVENT.size <= len(data):
                wd, mask, cookie, name_len = EVENT.unpack_from(data, offset)
                offset += EVENT.size
                raw_name = data[offset : offset + name_len].split(b"\0", 1)[0]
                offset += name_len
                base = self.wd_to_dir.get(wd)
                if base is None:
                    if mask & IN_Q_OVERFLOW:
                        yield "", mask, cookie, ""
                    continue
                if mask & IN_IGNORED:
                    self.wd_to_dir.pop(wd, None)
                    if self.dir_to_wd.get(base) == wd:
                        self.dir_to_wd.pop(base, None)
                name = os.fsdecode(raw_name)
                path = os.path.join(base, name) if name else base
                yield path, mask, cookie, base

    def close(self) -> None:
        if self.fd >= 0:
            os.close(self.fd)
            self.fd = -1


class AppendWatch:
    def __init__(self, root: str, report: str, debounce_ms: int) -> None:
        self.root = os.path.realpath(root)
        self.report = report
        self.debounce = debounce_ms / 1000.0
        self.records: Dict[str, Record] = {}
        self.ino = Inotify()
        self.stop = False
        self.pending: Dict[str, float] = {}
        self.report_abs: Optional[str] = None
        self.report_tmp_prefix: Optional[str] = None

        if report != "-":
            self.report_abs = os.path.realpath(report)
            report_dir = os.path.dirname(self.report_abs)
            report_name = os.path.basename(self.report_abs)
            self.report_tmp_prefix = os.path.join(report_dir, f".{report_name}.tmp.")

    def rel(self, path: str) -> str:
        return os.path.relpath(path, self.root)

    def excluded(self, path: str) -> bool:
        absolute = os.path.abspath(path)
        if self.report_abs and absolute == self.report_abs:
            return True
        if self.report_tmp_prefix and absolute.startswith(self.report_tmp_prefix):
            return True
        return False

    @staticmethod
    def regular_lstat(path: str) -> Optional[os.stat_result]:
        try:
            st = os.lstat(path)
        except (FileNotFoundError, PermissionError, OSError):
            return None
        return st if stat.S_ISREG(st.st_mode) else None

    @staticmethod
    def replacement_reason(mode: int) -> str:
        if stat.S_ISDIR(mode):
            kind = "a directory"
        elif stat.S_ISLNK(mode):
            kind = "a symbolic link"
        elif stat.S_ISFIFO(mode):
            kind = "a FIFO"
        else:
            kind = "a non-regular file"
        return f"path was replaced by {kind}"

    def walk_regular(self) -> Dict[str, os.stat_result]:
        found: Dict[str, os.stat_result] = {}
        stack = [self.root]
        while stack:
            directory = stack.pop()
            try:
                with os.scandir(directory) as it:
                    entries = list(it)
            except (FileNotFoundError, NotADirectoryError, PermissionError, OSError):
                continue
            for entry in entries:
                path = entry.path
                if self.excluded(path):
                    continue
                try:
                    if entry.is_dir(follow_symlinks=False):
                        stack.append(path)
                    elif entry.is_file(follow_symlinks=False):
                        st = entry.stat(follow_symlinks=False)
                        found[self.rel(path)] = st
                except (FileNotFoundError, PermissionError, OSError):
                    continue
        return found

    def rebuild_watches(self) -> bool:
        directories: set[str] = set()
        stack = [self.root]
        while stack:
            directory = stack.pop()
            directories.add(directory)
            try:
                with os.scandir(directory) as it:
                    entries = list(it)
            except PermissionError:
                self.ino.unwatched_dirs[directory] = (
                    "directory could not be watched: permission denied"
                )
                continue
            except (FileNotFoundError, NotADirectoryError):
                self.ino.unwatched_dirs.pop(directory, None)

